    _near_path_out_T_2
      ? _near_path_mods_1_io_out_sig_is_zero
      : _near_path_mods_0_io_out_sig_is_zero;
  assign io_out_near_path_lza_error =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_lza_error
      : _near_path_mods_0_io_out_lza_error;
  assign io_out_near_path_int_bit =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_int_bit
      : _near_path_mods_0_io_out_int_bit;
  assign io_out_near_path_sig_raw =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_sig_raw
      : _near_path_mods_0_io_out_sig_raw;
  assign io_out_near_path_lzc =
    _near_path_out_T_2 ? _near_path_mods_1_io_out_lzc : _near_path_mods_0_io_out_lzc;
  assign io_out_sel_far_path =
    ~eff_sub
    | (|(_exp_diff_a_b_T_2[8] ? _exp_diff_b_a_T_2[7:1] : _exp_diff_a_b_T_2[7:1]));
endmodule

module RoundingUnit(
  input  [22:0] io_in,
  input         io_roundIn,
                io_stickyIn,
                io_signIn,
  input  [2:0]  io_rm,
  output [22:0] io_out,
  output        io_inexact,
                io_cout
);

  wire inexact = io_roundIn | io_stickyIn;
  wire r_up =
    io_rm == 3'h4
      ? io_roundIn
      : io_rm == 3'h2
          ? inexact & io_signIn
          : io_rm == 3'h3
              ? inexact & ~io_signIn
              : io_rm != 3'h1 & io_rm == 3'h0
                & (io_roundIn & io_stickyIn | io_roundIn & ~io_stickyIn & io_in[0]);
  assign io_out = r_up ? io_in + 23'h1 : io_in;
  assign io_inexact = inexact;
  assign io_cout = r_up & (&io_in);
endmodule

module TininessRounder(
  input         io_in_sign,
  input  [26:0] io_in_sig,
  input  [2:0]  io_rm,
  output        io_tininess
);

  wire _rounder_io_cout;
  RoundingUnit rounder (
    .io_in       (io_in_sig[24:2]),
    .io_roundIn  (io_in_sig[1]),
    .io_stickyIn (io_in_sig[0]),
    .io_signIn   (io_in_sign),
    .io_rm       (io_rm),
    .io_out      (/* unused */),
    .io_inexact  (/* unused */),
    .io_cout     (_rounder_io_cout)
  );
  assign io_tininess =
    io_in_sig[26:25] == 2'h0 | io_in_sig[26:25] == 2'h1 & ~_rounder_io_cout;
endmodule

module FCMA_ADD_s2(
  input  [2:0]  io_in_rm,
  input         io_in_far_path_out_sign,
                io_in_near_path_out_sign,
  input  [7:0]  io_in_near_path_out_exp,
  input         io_in_special_case_valid,
                io_in_special_case_bits_iv,
                io_in_special_case_bits_nan,
                io_in_special_case_bits_inf_sign,
                io_in_small_add,
                io_in_far_path_mul_of,
  input  [23:0] io_in_far_sig_a,
  input  [27:0] io_in_far_sig_b,
  input  [7:0]  io_in_far_exp_a_vec_0,
                io_in_far_exp_a_vec_1,
                io_in_far_exp_a_vec_2,
  input         io_in_near_path_sig_is_zero,
                io_in_near_path_lza_error,
                io_in_near_path_int_bit,
  input  [24:0] io_in_near_path_sig_raw,
  input  [4:0]  io_in_near_path_lzc,
  input         io_in_sel_far_path,
  output [31:0] io_result,
  output [4:0]  io_fflags
);

  wire [7:0]  near_path_res_exp;
  wire [22:0] _near_path_rounder_io_out;
  wire        _near_path_rounder_io_inexact;
  wire        _near_path_rounder_io_cout;
  wire        _near_path_tininess_rounder_io_tininess;
  wire [22:0] _far_path_rounder_io_out;
  wire        _far_path_rounder_io_inexact;
  wire        _far_path_rounder_io_cout;
  wire        _far_path_tininess_rounder_io_tininess;
  wire [27:0] _adder_result_T = {1'h0, io_in_far_sig_a, 3'h0} + io_in_far_sig_b;
  wire        keep = _adder_result_T[27:26] == 2'h1;
  wire        cancellation = _adder_result_T[27:26] == 2'h0;
  wire [26:0] _far_path_res_sig_T_21 =
    (_adder_result_T[27] ? {_adder_result_T[27:2], |(_adder_result_T[1:0])} : 27'h0)
    | (keep | io_in_small_add ? _adder_result_T[26:0] : 27'h0)
    | (cancellation & ~io_in_small_add ? {_adder_result_T[25:0], 1'h0} : 27'h0);
  wire [7:0]  _far_path_res_exp_T_4 =
    (_adder_result_T[27] ? io_in_far_exp_a_vec_0 : 8'h0)
    | (keep ? io_in_far_exp_a_vec_1 : 8'h0)
    | (cancellation ? io_in_far_exp_a_vec_2 : 8'h0);
  wire        far_path_of =
    (&_far_path_res_exp_T_4) | _far_path_rounder_io_cout & _far_path_res_exp_T_4 == 8'hFE
    | io_in_far_path_mul_of;
  wire        far_path_ix = _far_path_rounder_io_inexact | far_path_of;
  wire        near_path_is_zero = near_path_res_exp == 8'h0 & io_in_near_path_sig_is_zero;
  assign near_path_res_exp =
    io_in_near_path_int_bit
      ? io_in_near_path_out_exp - {3'h0, io_in_near_path_lzc}
        - {7'h0, io_in_near_path_lza_error}
      : 8'h0;
  wire [55:0] _sig_s1_T = {31'h0, io_in_near_path_sig_raw} << io_in_near_path_lzc;
  wire [24:0] sig_s2 =
    io_in_near_path_lza_error ? {_sig_s1_T[23:0], 1'h0} : _sig_s1_T[24:0];
  wire [7:0]  _near_path_exp_rounded_T =
    {7'h0, _near_path_rounder_io_cout} + near_path_res_exp;
  wire        near_path_zero_sign = io_in_rm == 3'h2;
  wire        near_path_ix = _near_path_rounder_io_inexact | (&_near_path_exp_rounded_T);
  wire        common_overflow =
    io_in_sel_far_path & far_path_of | ~io_in_sel_far_path & (&_near_path_exp_rounded_T);
  wire        rmin =
    io_in_rm == 3'h1 | near_path_zero_sign & ~io_in_far_path_out_sign | io_in_rm == 3'h3
    & io_in_far_path_out_sign;
  TininessRounder far_path_tininess_rounder (
    .io_in_sign  (io_in_far_path_out_sign),
    .io_in_sig   (_far_path_res_sig_T_21),
    .io_rm       (io_in_rm),
    .io_tininess (_far_path_tininess_rounder_io_tininess)
  );
  RoundingUnit far_path_rounder (
    .io_in       (_far_path_res_sig_T_21[25:3]),
    .io_roundIn  (_far_path_res_sig_T_21[2]),
    .io_stickyIn (|(_far_path_res_sig_T_21[1:0])),
    .io_signIn   (io_in_far_path_out_sign),
    .io_rm       (io_in_rm),
    .io_out      (_far_path_rounder_io_out),
    .io_inexact  (_far_path_rounder_io_inexact),
    .io_cout     (_far_path_rounder_io_cout)
  );
  TininessRounder near_path_tininess_rounder (
    .io_in_sign  (io_in_near_path_out_sign),
    .io_in_sig   ({sig_s2, 2'h0}),
    .io_rm       (io_in_rm),
    .io_tininess (_near_path_tininess_rounder_io_tininess)
  );
  RoundingUnit near_path_rounder (
    .io_in       (sig_s2[23:1]),
    .io_roundIn  (sig_s2[0]),
    .io_stickyIn (1'h0),
    .io_signIn   (io_in_near_path_out_sign),
    .io_rm       (io_in_rm),
    .io_out      (_near_path_rounder_io_out),
    .io_inexact  (_near_path_rounder_io_inexact),
    .io_cout     (_near_path_rounder_io_cout)
  );
  assign io_result =
    io_in_special_case_valid
      ? (io_in_special_case_bits_nan
           ? 32'h7FC00000
           : {io_in_special_case_bits_inf_sign, 31'h7F800000})
      : common_overflow
          ? {io_in_sel_far_path ? io_in_far_path_out_sign : io_in_near_path_out_sign,
             7'h7F,
             ~rmin,
             {23{rmin}}}
          : io_in_sel_far_path
              ? {io_in_far_path_out_sign,
                 {7'h0, _far_path_rounder_io_cout} + _far_path_res_exp_T_4,
                 _far_path_rounder_io_out}
              : {io_in_near_path_out_sign & ~near_path_is_zero | near_path_zero_sign
                   & near_path_is_zero,
                 _near_path_exp_rounded_T,
                 _near_path_rounder_io_out};
  assign io_fflags =
    io_in_special_case_valid
      ? {io_in_special_case_bits_iv, 4'h0}
      : {2'h0,
         common_overflow,
         io_in_sel_far_path & io_in_small_add & _far_path_tininess_rounder_io_tininess
           & ~io_in_far_path_mul_of & far_path_ix | ~io_in_sel_far_path
           & _near_path_tininess_rounder_io_tininess & near_path_ix,
         io_in_sel_far_path & far_path_ix | ~io_in_sel_far_path & near_path_ix};
endmodule

module AccumulatorBaseInner(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [31:0] io_in_bits_a,
                io_in_bits_b,
  input  [2:0]  io_in_bits_rm,
  input  [3:0]  io_in_bits_dataType,
  input         io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_result,
  output [4:0]  io_out_bits_fflags
);

  wire        s1_ready;
  wire [31:0] _addS2_io_result;
  wire [4:0]  _addS2_io_fflags;
  wire [2:0]  _addS1_io_out_rm;
  wire        _addS1_io_out_far_path_out_sign;
  wire        _addS1_io_out_near_path_out_sign;
  wire [7:0]  _addS1_io_out_near_path_out_exp;
  wire        _addS1_io_out_special_case_valid;
  wire        _addS1_io_out_special_case_bits_iv;
  wire        _addS1_io_out_special_case_bits_nan;
  wire        _addS1_io_out_special_case_bits_inf_sign;
  wire        _addS1_io_out_small_add;
  wire        _addS1_io_out_far_path_mul_of;
  wire [23:0] _addS1_io_out_far_sig_a;
  wire [27:0] _addS1_io_out_far_sig_b;
  wire [7:0]  _addS1_io_out_far_exp_a_vec_0;
  wire [7:0]  _addS1_io_out_far_exp_a_vec_1;
  wire [7:0]  _addS1_io_out_far_exp_a_vec_2;
  wire        _addS1_io_out_near_path_sig_is_zero;
  wire        _addS1_io_out_near_path_lza_error;
  wire        _addS1_io_out_near_path_int_bit;
  wire [24:0] _addS1_io_out_near_path_sig_raw;
  wire [4:0]  _addS1_io_out_near_path_lzc;
  wire        _addS1_io_out_sel_far_path;
  reg         s0Pipe_rValid;
  reg  [2:0]  s0Pipe_rBits_addS1Out_rm;
  reg         s0Pipe_rBits_addS1Out_far_path_out_sign;
  reg         s0Pipe_rBits_addS1Out_near_path_out_sign;
  reg  [7:0]  s0Pipe_rBits_addS1Out_near_path_out_exp;
  reg         s0Pipe_rBits_addS1Out_special_case_valid;
  reg         s0Pipe_rBits_addS1Out_special_case_bits_iv;
  reg         s0Pipe_rBits_addS1Out_special_case_bits_nan;
  reg         s0Pipe_rBits_addS1Out_special_case_bits_inf_sign;
  reg         s0Pipe_rBits_addS1Out_small_add;
  reg         s0Pipe_rBits_addS1Out_far_path_mul_of;
  reg  [23:0] s0Pipe_rBits_addS1Out_far_sig_a;
  reg  [27:0] s0Pipe_rBits_addS1Out_far_sig_b;
  reg  [7:0]  s0Pipe_rBits_addS1Out_far_exp_a_vec_0;
  reg  [7:0]  s0Pipe_rBits_addS1Out_far_exp_a_vec_1;
  reg  [7:0]  s0Pipe_rBits_addS1Out_far_exp_a_vec_2;
  reg         s0Pipe_rBits_addS1Out_near_path_sig_is_zero;
  reg         s0Pipe_rBits_addS1Out_near_path_lza_error;
  reg         s0Pipe_rBits_addS1Out_near_path_int_bit;
  reg  [24:0] s0Pipe_rBits_addS1Out_near_path_sig_raw;
  reg  [4:0]  s0Pipe_rBits_addS1Out_near_path_lzc;
  reg         s0Pipe_rBits_addS1Out_sel_far_path;
  reg         s0Pipe_rBits_isFP;
  reg  [31:0] s0Pipe_rBits_intResult;
  reg  [4:0]  s0Pipe_rBits_intFlags;
  wire        s0_ready = ~s0Pipe_rValid | s1_ready;
  reg         io_out_rValid;
  reg  [31:0] io_out_rBits_result;
  reg  [4:0]  io_out_rBits_fflags;
  assign s1_ready = ~io_out_rValid | io_out_ready;
  always @(posedge clock) begin
    automatic logic _s0Pipe_T;
    automatic logic _io_out_T;
    _s0Pipe_T = s0_ready & io_in_valid;
    _io_out_T = s1_ready & s0Pipe_rValid;
    if (reset) begin
      s0Pipe_rValid <= 1'h0;
      io_out_rValid <= 1'h0;
    end
    else begin
      s0Pipe_rValid <= _s0Pipe_T | ~(s1_ready & s0Pipe_rValid) & s0Pipe_rValid;
      io_out_rValid <= _io_out_T | ~(io_out_ready & io_out_rValid) & io_out_rValid;
    end
    if (_s0Pipe_T) begin
      automatic logic [31:0] s0_bits_intResult = io_in_bits_a + io_in_bits_b;
      s0Pipe_rBits_addS1Out_rm <= _addS1_io_out_rm;
      s0Pipe_rBits_addS1Out_far_path_out_sign <= _addS1_io_out_far_path_out_sign;
      s0Pipe_rBits_addS1Out_near_path_out_sign <= _addS1_io_out_near_path_out_sign;
      s0Pipe_rBits_addS1Out_near_path_out_exp <= _addS1_io_out_near_path_out_exp;
      s0Pipe_rBits_addS1Out_special_case_valid <= _addS1_io_out_special_case_valid;
      s0Pipe_rBits_addS1Out_special_case_bits_iv <= _addS1_io_out_special_case_bits_iv;
      s0Pipe_rBits_addS1Out_special_case_bits_nan <= _addS1_io_out_special_case_bits_nan;
      s0Pipe_rBits_addS1Out_special_case_bits_inf_sign <=
        _addS1_io_out_special_case_bits_inf_sign;
      s0Pipe_rBits_addS1Out_small_add <= _addS1_io_out_small_add;
      s0Pipe_rBits_addS1Out_far_path_mul_of <= _addS1_io_out_far_path_mul_of;
      s0Pipe_rBits_addS1Out_far_sig_a <= _addS1_io_out_far_sig_a;
      s0Pipe_rBits_addS1Out_far_sig_b <= _addS1_io_out_far_sig_b;
      s0Pipe_rBits_addS1Out_far_exp_a_vec_0 <= _addS1_io_out_far_exp_a_vec_0;
      s0Pipe_rBits_addS1Out_far_exp_a_vec_1 <= _addS1_io_out_far_exp_a_vec_1;
      s0Pipe_rBits_addS1Out_far_exp_a_vec_2 <= _addS1_io_out_far_exp_a_vec_2;
      s0Pipe_rBits_addS1Out_near_path_sig_is_zero <= _addS1_io_out_near_path_sig_is_zero;
      s0Pipe_rBits_addS1Out_near_path_lza_error <= _addS1_io_out_near_path_lza_error;
      s0Pipe_rBits_addS1Out_near_path_int_bit <= _addS1_io_out_near_path_int_bit;
      s0Pipe_rBits_addS1Out_near_path_sig_raw <= _addS1_io_out_near_path_sig_raw;
      s0Pipe_rBits_addS1Out_near_path_lzc <= _addS1_io_out_near_path_lzc;
      s0Pipe_rBits_addS1Out_sel_far_path <= _addS1_io_out_sel_far_path;
      s0Pipe_rBits_isFP <= io_in_bits_dataType == 4'h1 | io_in_bits_dataType == 4'hB;
      s0Pipe_rBits_intResult <= s0_bits_intResult;
      s0Pipe_rBits_intFlags <=
        {4'h0,
         io_in_bits_a[31] == io_in_bits_b[31]
           & s0_bits_intResult[31] != io_in_bits_a[31]};
    end
    if (_io_out_T) begin
      io_out_rBits_result <=
        s0Pipe_rBits_isFP ? _addS2_io_result : s0Pipe_rBits_intResult;
      io_out_rBits_fflags <= s0Pipe_rBits_isFP ? _addS2_io_fflags : s0Pipe_rBits_intFlags;
    end
  end // always @(posedge)
  FCMA_ADD_s1 addS1 (
    .io_a                              (io_in_bits_a),
    .io_b                              (io_in_bits_b),
    .io_rm                             (io_in_bits_rm),
    .io_out_rm                         (_addS1_io_out_rm),
    .io_out_far_path_out_sign          (_addS1_io_out_far_path_out_sign),
    .io_out_near_path_out_sign         (_addS1_io_out_near_path_out_sign),
    .io_out_near_path_out_exp          (_addS1_io_out_near_path_out_exp),
    .io_out_special_case_valid         (_addS1_io_out_special_case_valid),
    .io_out_special_case_bits_iv       (_addS1_io_out_special_case_bits_iv),
    .io_out_special_case_bits_nan      (_addS1_io_out_special_case_bits_nan),
    .io_out_special_case_bits_inf_sign (_addS1_io_out_special_case_bits_inf_sign),
    .io_out_small_add                  (_addS1_io_out_small_add),
    .io_out_far_path_mul_of            (_addS1_io_out_far_path_mul_of),
    .io_out_far_sig_a                  (_addS1_io_out_far_sig_a),
    .io_out_far_sig_b                  (_addS1_io_out_far_sig_b),
    .io_out_far_exp_a_vec_0            (_addS1_io_out_far_exp_a_vec_0),
    .io_out_far_exp_a_vec_1            (_addS1_io_out_far_exp_a_vec_1),
    .io_out_far_exp_a_vec_2            (_addS1_io_out_far_exp_a_vec_2),
    .io_out_near_path_sig_is_zero      (_addS1_io_out_near_path_sig_is_zero),
    .io_out_near_path_lza_error        (_addS1_io_out_near_path_lza_error),
    .io_out_near_path_int_bit          (_addS1_io_out_near_path_int_bit),
    .io_out_near_path_sig_raw          (_addS1_io_out_near_path_sig_raw),
    .io_out_near_path_lzc              (_addS1_io_out_near_path_lzc),
    .io_out_sel_far_path               (_addS1_io_out_sel_far_path)
  );
  FCMA_ADD_s2 addS2 (
    .io_in_rm                         (s0Pipe_rBits_addS1Out_rm),
    .io_in_far_path_out_sign          (s0Pipe_rBits_addS1Out_far_path_out_sign),
    .io_in_near_path_out_sign         (s0Pipe_rBits_addS1Out_near_path_out_sign),
    .io_in_near_path_out_exp          (s0Pipe_rBits_addS1Out_near_path_out_exp),
    .io_in_special_case_valid         (s0Pipe_rBits_addS1Out_special_case_valid),
    .io_in_special_case_bits_iv       (s0Pipe_rBits_addS1Out_special_case_bits_iv),
    .io_in_special_case_bits_nan      (s0Pipe_rBits_addS1Out_special_case_bits_nan),
    .io_in_special_case_bits_inf_sign (s0Pipe_rBits_addS1Out_special_case_bits_inf_sign),
    .io_in_small_add                  (s0Pipe_rBits_addS1Out_small_add),
    .io_in_far_path_mul_of            (s0Pipe_rBits_addS1Out_far_path_mul_of),
    .io_in_far_sig_a                  (s0Pipe_rBits_addS1Out_far_sig_a),
    .io_in_far_sig_b                  (s0Pipe_rBits_addS1Out_far_sig_b),
    .io_in_far_exp_a_vec_0            (s0Pipe_rBits_addS1Out_far_exp_a_vec_0),
    .io_in_far_exp_a_vec_1            (s0Pipe_rBits_addS1Out_far_exp_a_vec_1),
    .io_in_far_exp_a_vec_2            (s0Pipe_rBits_addS1Out_far_exp_a_vec_2),
    .io_in_near_path_sig_is_zero      (s0Pipe_rBits_addS1Out_near_path_sig_is_zero),
    .io_in_near_path_lza_error        (s0Pipe_rBits_addS1Out_near_path_lza_error),
    .io_in_near_path_int_bit          (s0Pipe_rBits_addS1Out_near_path_int_bit),
    .io_in_near_path_sig_raw          (s0Pipe_rBits_addS1Out_near_path_sig_raw),
    .io_in_near_path_lzc              (s0Pipe_rBits_addS1Out_near_path_lzc),
    .io_in_sel_far_path               (s0Pipe_rBits_addS1Out_sel_far_path),
    .io_result                        (_addS2_io_result),
    .io_fflags                        (_addS2_io_fflags)
  );
  assign io_in_ready = s0_ready;
  assign io_out_valid = io_out_rValid;
  assign io_out_bits_result = io_out_rBits_result;
  assign io_out_bits_fflags = io_out_rBits_fflags;
endmodule

module AccumulatorBaseWrapper(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [31:0] io_in_bits_a,
                io_in_bits_b,
  input  [2:0]  io_in_bits_rm,
  input  [3:0]  io_in_bits_dataType,
  input         io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_result,
  output [4:0]  io_out_bits_fflags
);

  AccumulatorBaseInner core (
    .clock               (clock),
    .reset               (reset),
    .io_in_ready         (io_in_ready),
    .io_in_valid         (io_in_valid),
    .io_in_bits_a        (io_in_bits_a),
    .io_in_bits_b        (io_in_bits_b),
    .io_in_bits_rm       (io_in_bits_rm),
    .io_in_bits_dataType (io_in_bits_dataType),
    .io_out_ready        (io_out_ready),
    .io_out_valid        (io_out_valid),
    .io_out_bits_result  (io_out_bits_result),
    .io_out_bits_fflags  (io_out_bits_fflags)
  );
endmodule

module NaiveMultiplier(
  input         clock,
  input  [11:0] io_a,
                io_b,
  input         io_regEnables_0,
  output [23:0] io_result
);

  reg [11:0] io_result_r;
  reg [11:0] io_result_r_1;
  always @(posedge clock) begin
    if (io_regEnables_0) begin
      io_result_r <= io_a;
      io_result_r_1 <= io_b;
    end
  end // always @(posedge)
  assign io_result = {12'h0, io_result_r} * {12'h0, io_result_r_1};
endmodule

module CLZ_2(
  input  [23:0] io_in,
  output [4:0]  io_out
);

  assign io_out =
    io_in[23]
      ? 5'h0
      : io_in[22]
          ? 5'h1
          : io_in[21]
              ? 5'h2
              : io_in[20]
                  ? 5'h3
                  : io_in[19]
                      ? 5'h4
                      : io_in[18]
                          ? 5'h5
                          : io_in[17]
                              ? 5'h6
                              : io_in[16]
                                  ? 5'h7
                                  : io_in[15]
                                      ? 5'h8
                                      : io_in[14]
                                          ? 5'h9
                                          : io_in[13]
                                              ? 5'hA
                                              : io_in[12]
                                                  ? 5'hB
                                                  : io_in[11]
                                                      ? 5'hC
                                                      : io_in[10]
                                                          ? 5'hD
                                                          : io_in[9]
                                                              ? 5'hE
                                                              : io_in[8]
                                                                  ? 5'hF
                                                                  : io_in[7]
                                                                      ? 5'h10
                                                                      : io_in[6]
                                                                          ? 5'h11
                                                                          : io_in[5]
                                                                              ? 5'h12
                                                                              : io_in[4]
                                                                                  ? 5'h13
                                                                                  : io_in[3]
                                                                                      ? 5'h14
                                                                                      : io_in[2]
                                                                                          ? 5'h15
                                                                                          : {4'hB,
                                                                                             ~(io_in[1])};
endmodule

module FMUL_s1(
  input  [15:0] io_a,
                io_b,
  input  [2:0]  io_rm,
  output        io_out_special_case_valid,
                io_out_special_case_bits_nan,
                io_out_special_case_bits_inf,
                io_out_early_overflow,
                io_out_prod_sign,
  output [5:0]  io_out_shift_amt,
                io_out_exp_shifted,
  output        io_out_may_be_subnormal,
  output [2:0]  io_out_rm
);

  wire [4:0] _lzc_clz_io_out;
  wire [5:0] exp_sum =
    {1'h0, io_a[14:11], io_a[10] | ~(|(io_a[14:10]))}
    + {1'h0, io_b[14:11], io_b[10] | ~(|(io_b[14:10]))};
  wire [6:0] _shift_lim_sub_T_1 = {1'h0, exp_sum} - 7'h2;
  wire [5:0] _GEN = {1'h0, _lzc_clz_io_out};
  wire       exceed_lim = _shift_lim_sub_T_1[5:0] <= _GEN;
  wire [5:0] shift_amt =
    _shift_lim_sub_T_1[6] ? 6'h0 : exceed_lim ? _shift_lim_sub_T_1[5:0] : _GEN;
  wire       hasZero =
    ~(|(io_a[14:10])) & ~(|(io_a[9:0])) | ~(|(io_b[14:10])) & ~(|(io_b[9:0]));
  wire       hasNaN =
    (&(io_a[14:10])) & (|(io_a[9:0])) | (&(io_b[14:10])) & (|(io_b[9:0]));
  wire       hasInf =
    (&(io_a[14:10])) & ~(|(io_a[9:0])) | (&(io_b[14:10])) & ~(|(io_b[9:0]));
  CLZ_2 lzc_clz (
    .io_in
      ({13'h0,
        (|(io_a[14:10])) ? {|(io_b[14:10]), io_b[9:0]} : {|(io_a[14:10]), io_a[9:0]}}),
    .io_out (_lzc_clz_io_out)
  );
  assign io_out_special_case_valid = hasZero | hasNaN | hasInf;
  assign io_out_special_case_bits_nan = hasNaN | hasZero & hasInf;
  assign io_out_special_case_bits_inf = hasInf;
  assign io_out_early_overflow = exp_sum > 6'h2D;
  assign io_out_prod_sign = io_a[15] ^ io_b[15];
  assign io_out_shift_amt = shift_amt;
  assign io_out_exp_shifted = exp_sum - 6'h1 - shift_amt;
  assign io_out_may_be_subnormal = exceed_lim | _shift_lim_sub_T_1[6];
  assign io_out_rm = io_rm;
endmodule

module FMUL_s2(
  input         io_in_special_case_valid,
                io_in_special_case_bits_nan,
                io_in_special_case_bits_inf,
                io_in_early_overflow,
                io_in_prod_sign,
  input  [5:0]  io_in_shift_amt,
                io_in_exp_shifted,
  input         io_in_may_be_subnormal,
  input  [2:0]  io_in_rm,
  input  [21:0] io_prod,
  output        io_out_special_case_valid,
                io_out_special_case_bits_nan,
                io_out_special_case_bits_inf,
                io_out_raw_out_sign,
  output [5:0]  io_out_raw_out_exp,
  output [34:0] io_out_raw_out_sig,
  output        io_out_early_overflow,
  output [2:0]  io_out_rm
);

  wire [97:0] _sig_shifted_raw_T = {76'h0, io_prod} << io_in_shift_amt;
  wire        exp_is_subnormal = io_in_may_be_subnormal & ~(_sig_shifted_raw_T[34]);
  wire        no_extra_shift = _sig_shifted_raw_T[34] | exp_is_subnormal;
  assign io_out_special_case_valid = io_in_special_case_valid;
  assign io_out_special_case_bits_nan = io_in_special_case_bits_nan;
  assign io_out_special_case_bits_inf = io_in_special_case_bits_inf;
  assign io_out_raw_out_sign = io_in_prod_sign;
  assign io_out_raw_out_exp =
    exp_is_subnormal
      ? 6'h0
      : no_extra_shift ? io_in_exp_shifted : io_in_exp_shifted - 6'h1;
  assign io_out_raw_out_sig =
    no_extra_shift ? _sig_shifted_raw_T[34:0] : {_sig_shifted_raw_T[33:0], 1'h0};
  assign io_out_early_overflow = io_in_early_overflow;
  assign io_out_rm = io_in_rm;
endmodule

module RoundingUnit_4(
  input  [9:0] io_in,
  input        io_roundIn,
               io_stickyIn,
               io_signIn,
  input  [2:0] io_rm,
  output [9:0] io_out,
  output       io_cout
);

  wire inexact = io_roundIn | io_stickyIn;
  wire r_up =
    io_rm == 3'h4
      ? io_roundIn
      : io_rm == 3'h2
          ? inexact & io_signIn
          : io_rm == 3'h3
              ? inexact & ~io_signIn
              : io_rm != 3'h1 & io_rm == 3'h0
                & (io_roundIn & io_stickyIn | io_roundIn & ~io_stickyIn & io_in[0]);
  assign io_out = r_up ? io_in + 10'h1 : io_in;
  assign io_cout = r_up & (&io_in);
endmodule

module FMUL_s3(
  input         io_in_special_case_valid,
                io_in_special_case_bits_nan,
                io_in_special_case_bits_inf,
                io_in_raw_out_sign,
  input  [5:0]  io_in_raw_out_exp,
  input  [34:0] io_in_raw_out_sig,
  input         io_in_early_overflow,
  input  [2:0]  io_in_rm,
  output [15:0] io_result
);

  wire [9:0] _rounder_io_out;
  wire       _rounder_io_cout;
  wire       common_of =
    (_rounder_io_cout ? io_in_raw_out_exp[4:0] == 5'h1E : (&(io_in_raw_out_exp[4:0])))
    | io_in_early_overflow;
  wire       rmin =
    io_in_rm == 3'h1 | io_in_rm == 3'h2 & ~io_in_raw_out_sign | io_in_rm == 3'h3
    & io_in_raw_out_sign;
  RoundingUnit_4 rounder (
    .io_in       (io_in_raw_out_sig[33:24]),
    .io_roundIn  (io_in_raw_out_sig[23]),
    .io_stickyIn (|{io_in_raw_out_sig[22], |(io_in_raw_out_sig[21:0])}),
    .io_signIn   (io_in_raw_out_sign),
    .io_rm       (io_in_rm),
    .io_out      (_rounder_io_out),
    .io_cout     (_rounder_io_cout)
  );
  assign io_result =
    io_in_special_case_valid
      ? (io_in_special_case_bits_nan
           ? 16'h7E00
           : {io_in_raw_out_sign, io_in_special_case_bits_inf ? 15'h7C00 : 15'h0})
      : {io_in_raw_out_sign,
         common_of ? {4'hF, ~rmin} : {4'h0, _rounder_io_cout} + io_in_raw_out_exp[4:0],
         common_of ? {10{rmin}} : _rounder_io_out};
endmodule

module TCMulPipe(
  input         clock,
                reset,
                io_in_valid,
  input  [15:0] io_in_bits_a,
                io_in_bits_b,
  input  [2:0]  io_in_bits_rm,
