module TCMulPipe_1(
  input         clock,
                reset,
                io_in_valid,
  input  [15:0] io_in_bits_a,
                io_in_bits_b,
  input  [2:0]  io_in_bits_rm,
  output        io_out_valid,
  output [15:0] io_out_bits_result
);

  wire        _s2_io_out_special_case_valid;
  wire        _s2_io_out_special_case_bits_nan;
  wire        _s2_io_out_special_case_bits_inf;
  wire        _s2_io_out_raw_out_sign;
  wire [5:0]  _s2_io_out_raw_out_exp;
  wire [34:0] _s2_io_out_raw_out_sig;
  wire        _s2_io_out_early_overflow;
  wire [2:0]  _s2_io_out_rm;
  wire        _s1_io_out_special_case_valid;
  wire        _s1_io_out_special_case_bits_nan;
  wire        _s1_io_out_special_case_bits_inf;
  wire        _s1_io_out_early_overflow;
  wire        _s1_io_out_prod_sign;
  wire [5:0]  _s1_io_out_shift_amt;
  wire [5:0]  _s1_io_out_exp_shifted;
  wire        _s1_io_out_may_be_subnormal;
  wire [2:0]  _s1_io_out_rm;
  wire [23:0] _multiplier_io_result;
  reg         REG;
  reg         REG_1;
  reg         s2_io_in_r_special_case_valid;
  reg         s2_io_in_r_special_case_bits_nan;
  reg         s2_io_in_r_special_case_bits_inf;
  reg         s2_io_in_r_early_overflow;
  reg         s2_io_in_r_prod_sign;
  reg  [5:0]  s2_io_in_r_shift_amt;
  reg  [5:0]  s2_io_in_r_exp_shifted;
  reg         s2_io_in_r_may_be_subnormal;
  reg  [2:0]  s2_io_in_r_rm;
  reg         s3_io_in_r_special_case_valid;
  reg         s3_io_in_r_special_case_bits_nan;
  reg         s3_io_in_r_special_case_bits_inf;
  reg         s3_io_in_r_raw_out_sign;
  reg  [5:0]  s3_io_in_r_raw_out_exp;
  reg  [34:0] s3_io_in_r_raw_out_sig;
  reg         s3_io_in_r_early_overflow;
  reg  [2:0]  s3_io_in_r_rm;
  always @(posedge clock) begin
    if (reset) begin
      REG <= 1'h0;
      REG_1 <= 1'h0;
    end
    else begin
      REG <= io_in_valid;
      REG_1 <= REG;
    end
    if (io_in_valid) begin
      s2_io_in_r_special_case_valid <= _s1_io_out_special_case_valid;
      s2_io_in_r_special_case_bits_nan <= _s1_io_out_special_case_bits_nan;
      s2_io_in_r_special_case_bits_inf <= _s1_io_out_special_case_bits_inf;
      s2_io_in_r_early_overflow <= _s1_io_out_early_overflow;
      s2_io_in_r_prod_sign <= _s1_io_out_prod_sign;
      s2_io_in_r_shift_amt <= _s1_io_out_shift_amt;
      s2_io_in_r_exp_shifted <= _s1_io_out_exp_shifted;
      s2_io_in_r_may_be_subnormal <= _s1_io_out_may_be_subnormal;
      s2_io_in_r_rm <= _s1_io_out_rm;
    end
    if (REG) begin
      s3_io_in_r_special_case_valid <= _s2_io_out_special_case_valid;
      s3_io_in_r_special_case_bits_nan <= _s2_io_out_special_case_bits_nan;
      s3_io_in_r_special_case_bits_inf <= _s2_io_out_special_case_bits_inf;
      s3_io_in_r_raw_out_sign <= _s2_io_out_raw_out_sign;
      s3_io_in_r_raw_out_exp <= _s2_io_out_raw_out_exp;
      s3_io_in_r_raw_out_sig <= _s2_io_out_raw_out_sig;
      s3_io_in_r_early_overflow <= _s2_io_out_early_overflow;
      s3_io_in_r_rm <= _s2_io_out_rm;
    end
  end // always @(posedge)
  NaiveMultiplier multiplier (
    .clock           (clock),
    .io_a            ({1'h0, |(io_in_bits_a[14:10]), io_in_bits_a[9:0]}),
    .io_b            ({1'h0, |(io_in_bits_b[14:10]), io_in_bits_b[9:0]}),
    .io_regEnables_0 (io_in_valid),
    .io_result       (_multiplier_io_result)
  );
  FMUL_s1 s1 (
    .io_a                         (io_in_bits_a),
    .io_b                         (io_in_bits_b),
    .io_rm                        (io_in_bits_rm),
    .io_out_special_case_valid    (_s1_io_out_special_case_valid),
    .io_out_special_case_bits_nan (_s1_io_out_special_case_bits_nan),
    .io_out_special_case_bits_inf (_s1_io_out_special_case_bits_inf),
    .io_out_early_overflow        (_s1_io_out_early_overflow),
    .io_out_prod_sign             (_s1_io_out_prod_sign),
    .io_out_shift_amt             (_s1_io_out_shift_amt),
    .io_out_exp_shifted           (_s1_io_out_exp_shifted),
    .io_out_may_be_subnormal      (_s1_io_out_may_be_subnormal),
    .io_out_rm                    (_s1_io_out_rm)
  );
  FMUL_s2 s2 (
    .io_in_special_case_valid     (s2_io_in_r_special_case_valid),
    .io_in_special_case_bits_nan  (s2_io_in_r_special_case_bits_nan),
    .io_in_special_case_bits_inf  (s2_io_in_r_special_case_bits_inf),
    .io_in_early_overflow         (s2_io_in_r_early_overflow),
    .io_in_prod_sign              (s2_io_in_r_prod_sign),
    .io_in_shift_amt              (s2_io_in_r_shift_amt),
    .io_in_exp_shifted            (s2_io_in_r_exp_shifted),
    .io_in_may_be_subnormal       (s2_io_in_r_may_be_subnormal),
    .io_in_rm                     (s2_io_in_r_rm),
    .io_prod                      (_multiplier_io_result[21:0]),
    .io_out_special_case_valid    (_s2_io_out_special_case_valid),
    .io_out_special_case_bits_nan (_s2_io_out_special_case_bits_nan),
    .io_out_special_case_bits_inf (_s2_io_out_special_case_bits_inf),
    .io_out_raw_out_sign          (_s2_io_out_raw_out_sign),
    .io_out_raw_out_exp           (_s2_io_out_raw_out_exp),
    .io_out_raw_out_sig           (_s2_io_out_raw_out_sig),
    .io_out_early_overflow        (_s2_io_out_early_overflow),
    .io_out_rm                    (_s2_io_out_rm)
  );
  FMUL_s3 s3 (
    .io_in_special_case_valid    (s3_io_in_r_special_case_valid),
    .io_in_special_case_bits_nan (s3_io_in_r_special_case_bits_nan),
    .io_in_special_case_bits_inf (s3_io_in_r_special_case_bits_inf),
    .io_in_raw_out_sign          (s3_io_in_r_raw_out_sign),
    .io_in_raw_out_exp           (s3_io_in_r_raw_out_exp),
    .io_in_raw_out_sig           (s3_io_in_r_raw_out_sig),
    .io_in_early_overflow        (s3_io_in_r_early_overflow),
    .io_in_rm                    (s3_io_in_r_rm),
    .io_result                   (io_out_bits_result)
  );
  assign io_out_valid = REG_1;
endmodule

module ShiftRightJam_1(
  input  [12:0] io_in,
  input  [4:0]  io_shamt,
  output [12:0] io_out,
  output        io_sticky
);

  wire        exceed_max_shift = io_shamt > 5'hD;
  wire [15:0] _sticky_mask_T = 16'h1 << io_shamt[3:0];
  assign io_out = exceed_max_shift ? 13'h0 : io_in >> io_shamt;
  assign io_sticky = |(io_in & (_sticky_mask_T[12:0] - 13'h1 | {13{exceed_max_shift}}));
endmodule

module FarPath_1(
  input         io_in_a_sign,
  input  [4:0]  io_in_a_exp,
  input  [10:0] io_in_a_sig,
                io_in_b_sig,
  input  [4:0]  io_in_expDiff,
  input         io_in_effSub,
  output        io_out_result_sign,
  output [10:0] io_out_sig_a,
  output [14:0] io_out_sig_b,
  output [4:0]  io_out_exp_a_vec_0,
                io_out_exp_a_vec_1,
                io_out_exp_a_vec_2
);

  wire [12:0] _shiftRightJam_io_out;
  wire        _shiftRightJam_io_sticky;
  ShiftRightJam_1 shiftRightJam (
    .io_in     ({io_in_b_sig, 2'h0}),
    .io_shamt  (io_in_expDiff),
    .io_out    (_shiftRightJam_io_out),
    .io_sticky (_shiftRightJam_io_sticky)
  );
  assign io_out_result_sign = io_in_a_sign;
  assign io_out_sig_a = io_in_a_sig;
  assign io_out_sig_b =
    (io_in_effSub
       ? {1'h1, ~_shiftRightJam_io_out, ~_shiftRightJam_io_sticky}
       : {1'h0, _shiftRightJam_io_out, _shiftRightJam_io_sticky}) + {14'h0, io_in_effSub};
  assign io_out_exp_a_vec_0 = io_in_a_exp + 5'h1;
  assign io_out_exp_a_vec_1 = io_in_a_exp;
  assign io_out_exp_a_vec_2 = io_in_a_exp - 5'h1;
endmodule

module LZA_2(
  input  [11:0] io_a,
                io_b,
  output [11:0] io_f
);

  assign io_f =
    {io_a[11] ^ io_b[11] ^ ~(~(io_a[10]) & ~(io_b[10])),
     io_a[10] ^ io_b[10] ^ ~(~(io_a[9]) & ~(io_b[9])),
     io_a[9] ^ io_b[9] ^ ~(~(io_a[8]) & ~(io_b[8])),
     io_a[8] ^ io_b[8] ^ ~(~(io_a[7]) & ~(io_b[7])),
     io_a[7] ^ io_b[7] ^ ~(~(io_a[6]) & ~(io_b[6])),
     io_a[6] ^ io_b[6] ^ ~(~(io_a[5]) & ~(io_b[5])),
     io_a[5] ^ io_b[5] ^ ~(~(io_a[4]) & ~(io_b[4])),
     io_a[4] ^ io_b[4] ^ ~(~(io_a[3]) & ~(io_b[3])),
     io_a[3] ^ io_b[3] ^ ~(~(io_a[2]) & ~(io_b[2])),
     io_a[2] ^ io_b[2] ^ ~(~(io_a[1]) & ~(io_b[1])),
     io_a[1] ^ io_b[1] ^ ~(~(io_a[0]) & ~(io_b[0])),
     1'h0};
endmodule

module CLZ_258(
  input  [11:0] io_in,
  output [3:0]  io_out
);

  assign io_out =
    io_in[11]
      ? 4'h0
      : io_in[10]
          ? 4'h1
          : io_in[9]
              ? 4'h2
              : io_in[8]
                  ? 4'h3
                  : io_in[7]
                      ? 4'h4
                      : io_in[6]
                          ? 4'h5
                          : io_in[5]
                              ? 4'h6
                              : io_in[4]
                                  ? 4'h7
                                  : io_in[3]
                                      ? 4'h8
                                      : io_in[2] ? 4'h9 : {3'h5, ~(io_in[1])};
endmodule

module NearPath_2(
  input         io_in_a_sign,
  input  [4:0]  io_in_a_exp,
  input  [10:0] io_in_a_sig,
  input         io_in_b_sign,
  input  [10:0] io_in_b_sig,
  input         io_in_need_shift_b,
  output        io_out_result_sign,
  output [4:0]  io_out_result_exp,
  output        io_out_sig_is_zero,
                io_out_a_lt_b,
                io_out_lza_error,
                io_out_int_bit,
  output [11:0] io_out_sig_raw,
  output [3:0]  io_out_lzc
);

  wire [11:0] _lza_ab_io_f;
  wire [11:0] b_sig = {io_in_b_sig, 1'h0} >> io_in_need_shift_b;
  wire [12:0] _a_minus_b_T_4 = {1'h0, io_in_a_sig, 1'h0} + {1'h1, ~b_sig} + 13'h1;
  wire        lza_str_zero = _lza_ab_io_f == 12'h0;
  wire        need_shift_lim = io_in_a_exp < 5'hC;
  wire [12:0] _shift_lim_mask_raw_T_2 = 13'h1000 >> io_in_a_exp[3:0];
  wire [11:0] lzc_str =
    (need_shift_lim ? _shift_lim_mask_raw_T_2[11:0] : 12'h0) | _lza_ab_io_f;
  wire        _int_bit_mask_T_5 = lzc_str[10] & ~(lzc_str[11]);
  wire        _int_bit_mask_T_10 = lzc_str[9] & lzc_str[11:10] == 2'h0;
  wire        _int_bit_mask_T_15 = lzc_str[8] & lzc_str[11:9] == 3'h0;
  wire        _int_bit_mask_T_20 = lzc_str[7] & lzc_str[11:8] == 4'h0;
  wire        _int_bit_mask_T_25 = lzc_str[6] & lzc_str[11:7] == 5'h0;
  wire        _int_bit_mask_T_30 = lzc_str[5] & lzc_str[11:6] == 6'h0;
  wire        _int_bit_mask_T_35 = lzc_str[4] & lzc_str[11:5] == 7'h0;
  wire        _int_bit_mask_T_40 = lzc_str[3] & lzc_str[11:4] == 8'h0;
  wire        _int_bit_mask_T_45 = lzc_str[2] & lzc_str[11:3] == 9'h0;
  wire        _int_bit_mask_T_50 = lzc_str[1] & lzc_str[11:2] == 10'h0;
  wire [11:0] _int_bit_predicted_T_1 =
    {lzc_str[11],
     _int_bit_mask_T_5,
     _int_bit_mask_T_10,
     _int_bit_mask_T_15,
     _int_bit_mask_T_20,
     _int_bit_mask_T_25,
     _int_bit_mask_T_30,
     _int_bit_mask_T_35,
     _int_bit_mask_T_40,
     _int_bit_mask_T_45,
     _int_bit_mask_T_50,
     lzc_str[0] & lzc_str[11:1] == 11'h0 | lza_str_zero} & _a_minus_b_T_4[11:0];
  wire        exceed_lim =
    need_shift_lim
    & ({_lza_ab_io_f[11],
        |(_lza_ab_io_f[11:10]),
        |(_lza_ab_io_f[11:9]),
        |(_lza_ab_io_f[11:8]),
        |(_lza_ab_io_f[11:7]),
        |(_lza_ab_io_f[11:6]),
        |(_lza_ab_io_f[11:5]),
        |(_lza_ab_io_f[11:4]),
        |(_lza_ab_io_f[11:3]),
        |(_lza_ab_io_f[11:2]),
        |(_lza_ab_io_f[11:1])} & _shift_lim_mask_raw_T_2[10:0]) == 11'h0;
  LZA_2 lza_ab (
    .io_a ({io_in_a_sig, 1'h0}),
    .io_b (~b_sig),
    .io_f (_lza_ab_io_f)
  );
  CLZ_258 lzc_clz (
    .io_in  (lzc_str),
    .io_out (io_out_lzc)
  );
  assign io_out_result_sign = _a_minus_b_T_4[12] ? io_in_b_sign : io_in_a_sign;
  assign io_out_result_exp = io_in_a_exp;
  assign io_out_sig_is_zero = lza_str_zero & ~(_a_minus_b_T_4[0]);
  assign io_out_a_lt_b = _a_minus_b_T_4[12];
  assign io_out_lza_error = ~(|_int_bit_predicted_T_1) & ~exceed_lim;
  assign io_out_int_bit =
    exceed_lim
      ? (|(_shift_lim_mask_raw_T_2[11:0] & _a_minus_b_T_4[11:0]))
      : (|(_a_minus_b_T_4[10:0]
           & {lzc_str[11],
              _int_bit_mask_T_5,
              _int_bit_mask_T_10,
              _int_bit_mask_T_15,
              _int_bit_mask_T_20,
              _int_bit_mask_T_25,
              _int_bit_mask_T_30,
              _int_bit_mask_T_35,
              _int_bit_mask_T_40,
              _int_bit_mask_T_45,
              _int_bit_mask_T_50})) | (|_int_bit_predicted_T_1);
  assign io_out_sig_raw = _a_minus_b_T_4[11:0];
endmodule

