  wire        _near_path_mods_0_io_out_int_bit;
  wire [11:0] _near_path_mods_0_io_out_sig_raw;
  wire [3:0]  _near_path_mods_0_io_out_lzc;
  wire        decode_a_isInf = (&(io_a[14:10])) & ~(|(io_a[9:0]));
  wire        decode_b_isInf = (&(io_b[14:10])) & ~(|(io_b[9:0]));
  wire        _GEN = io_a[10] | ~(|(io_a[14:10]));
  wire [4:0]  raw_a_exp = {io_a[14:11], _GEN};
  wire [10:0] raw_a_sig = {|(io_a[14:10]), io_a[9:0]};
  wire        _GEN_0 = io_b[10] | ~(|(io_b[14:10]));
  wire [4:0]  raw_b_exp = {io_b[14:11], _GEN_0};
  wire [10:0] raw_b_sig = {|(io_b[14:10]), io_b[9:0]};
  wire        eff_sub = io_a[15] ^ io_b[15];
  wire        special_path_hasNaN =
    (&(io_a[14:10])) & (|(io_a[9:0])) | (&(io_b[14:10])) & (|(io_b[9:0]));
  wire [5:0]  _exp_diff_a_b_T_2 = {1'h0, io_a[14:11], _GEN} - {1'h0, io_b[14:11], _GEN_0};
  wire [4:0]  _exp_diff_b_a_T_2 = {io_b[14:11], _GEN_0} - {io_a[14:11], _GEN};
  wire        near_path_exp_neq = {io_a[11], _GEN} != {io_b[11], _GEN_0};
  wire        _near_path_out_T_2 =
    _exp_diff_a_b_T_2[5] | ~near_path_exp_neq & _near_path_mods_0_io_out_a_lt_b;
  FarPath_1 far_path_mods_0 (
    .io_in_a_sign       (_exp_diff_a_b_T_2[5] ? io_b[15] : io_a[15]),
    .io_in_a_exp        (_exp_diff_a_b_T_2[5] ? raw_b_exp : raw_a_exp),
    .io_in_a_sig        (_exp_diff_a_b_T_2[5] ? raw_b_sig : raw_a_sig),
    .io_in_b_sig        (_exp_diff_a_b_T_2[5] ? raw_a_sig : raw_b_sig),
    .io_in_expDiff
      (_exp_diff_a_b_T_2[5] ? _exp_diff_b_a_T_2 : _exp_diff_a_b_T_2[4:0]),
    .io_in_effSub       (eff_sub),
    .io_out_result_sign (io_out_far_path_out_sign),
    .io_out_sig_a       (io_out_far_sig_a),
    .io_out_sig_b       (io_out_far_sig_b),
    .io_out_exp_a_vec_0 (io_out_far_exp_a_vec_0),
    .io_out_exp_a_vec_1 (io_out_far_exp_a_vec_1),
    .io_out_exp_a_vec_2 (io_out_far_exp_a_vec_2)
  );
  NearPath_2 near_path_mods_0 (
    .io_in_a_sign       (io_a[15]),
    .io_in_a_exp        (raw_a_exp),
    .io_in_a_sig        (raw_a_sig),
    .io_in_b_sign       (io_b[15]),
    .io_in_b_sig        (raw_b_sig),
    .io_in_need_shift_b (near_path_exp_neq),
    .io_out_result_sign (_near_path_mods_0_io_out_result_sign),
    .io_out_result_exp  (_near_path_mods_0_io_out_result_exp),
    .io_out_sig_is_zero (_near_path_mods_0_io_out_sig_is_zero),
    .io_out_a_lt_b      (_near_path_mods_0_io_out_a_lt_b),
    .io_out_lza_error   (_near_path_mods_0_io_out_lza_error),
    .io_out_int_bit     (_near_path_mods_0_io_out_int_bit),
    .io_out_sig_raw     (_near_path_mods_0_io_out_sig_raw),
    .io_out_lzc         (_near_path_mods_0_io_out_lzc)
  );
  NearPath_2 near_path_mods_1 (
    .io_in_a_sign       (io_b[15]),
    .io_in_a_exp        (raw_b_exp),
    .io_in_a_sig        (raw_b_sig),
    .io_in_b_sign       (io_a[15]),
    .io_in_b_sig        (raw_a_sig),
    .io_in_need_shift_b (near_path_exp_neq),
    .io_out_result_sign (_near_path_mods_1_io_out_result_sign),
    .io_out_result_exp  (_near_path_mods_1_io_out_result_exp),
    .io_out_sig_is_zero (_near_path_mods_1_io_out_sig_is_zero),
    .io_out_a_lt_b      (/* unused */),
    .io_out_lza_error   (_near_path_mods_1_io_out_lza_error),
    .io_out_int_bit     (_near_path_mods_1_io_out_int_bit),
    .io_out_sig_raw     (_near_path_mods_1_io_out_sig_raw),
    .io_out_lzc         (_near_path_mods_1_io_out_lzc)
  );
  assign io_out_rm = io_rm;
  assign io_out_near_path_out_sign =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_result_sign
      : _near_path_mods_0_io_out_result_sign;
  assign io_out_near_path_out_exp =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_result_exp
      : _near_path_mods_0_io_out_result_exp;
  assign io_out_special_case_valid =
    special_path_hasNaN | decode_a_isInf | decode_b_isInf;
  assign io_out_special_case_bits_nan =
    special_path_hasNaN | decode_a_isInf & decode_b_isInf & eff_sub;
  assign io_out_special_case_bits_inf_sign = decode_a_isInf ? io_a[15] : io_b[15];
  assign io_out_small_add = ~(|(io_a[14:10])) & ~(|(io_b[14:10]));
  assign io_out_far_path_mul_of = (&(io_b[14:10])) & ~eff_sub;
  assign io_out_near_path_sig_is_zero =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_sig_is_zero
      : _near_path_mods_0_io_out_sig_is_zero;
  assign io_out_near_path_lza_error =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_lza_error
      : _near_path_mods_0_io_out_lza_error;
  assign io_out_near_path_int_bit =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_int_bit
      : _near_path_mods_0_io_out_int_bit;
  assign io_out_near_path_sig_raw =
    _near_path_out_T_2
      ? _near_path_mods_1_io_out_sig_raw
      : _near_path_mods_0_io_out_sig_raw;
  assign io_out_near_path_lzc =
    _near_path_out_T_2 ? _near_path_mods_1_io_out_lzc : _near_path_mods_0_io_out_lzc;
  assign io_out_sel_far_path =
    ~eff_sub
    | (|(_exp_diff_a_b_T_2[5] ? _exp_diff_b_a_T_2[4:1] : _exp_diff_a_b_T_2[4:1]));
endmodule

module FCMA_ADD_s2_1(
  input  [2:0]  io_in_rm,
  input         io_in_far_path_out_sign,
                io_in_near_path_out_sign,
  input  [4:0]  io_in_near_path_out_exp,
  input         io_in_special_case_valid,
                io_in_special_case_bits_nan,
                io_in_special_case_bits_inf_sign,
                io_in_small_add,
                io_in_far_path_mul_of,
  input  [10:0] io_in_far_sig_a,
  input  [14:0] io_in_far_sig_b,
  input  [4:0]  io_in_far_exp_a_vec_0,
                io_in_far_exp_a_vec_1,
                io_in_far_exp_a_vec_2,
  input         io_in_near_path_sig_is_zero,
                io_in_near_path_lza_error,
                io_in_near_path_int_bit,
  input  [11:0] io_in_near_path_sig_raw,
  input  [3:0]  io_in_near_path_lzc,
  input         io_in_sel_far_path,
  output [15:0] io_result
);

  wire [4:0]  near_path_res_exp;
  wire [9:0]  _near_path_rounder_io_out;
  wire        _near_path_rounder_io_cout;
  wire [9:0]  _far_path_rounder_io_out;
  wire        _far_path_rounder_io_cout;
  wire [14:0] _adder_result_T = {1'h0, io_in_far_sig_a, 3'h0} + io_in_far_sig_b;
  wire        keep = _adder_result_T[14:13] == 2'h1;
  wire        cancellation = _adder_result_T[14:13] == 2'h0;
  wire [12:0] _far_path_res_sig_T_21 =
    (_adder_result_T[14] ? {_adder_result_T[13:2], |(_adder_result_T[1:0])} : 13'h0)
    | (keep | io_in_small_add ? _adder_result_T[12:0] : 13'h0)
    | (cancellation & ~io_in_small_add ? {_adder_result_T[11:0], 1'h0} : 13'h0);
  wire [4:0]  _far_path_res_exp_T_4 =
    (_adder_result_T[14] ? io_in_far_exp_a_vec_0 : 5'h0)
    | (keep ? io_in_far_exp_a_vec_1 : 5'h0)
    | (cancellation ? io_in_far_exp_a_vec_2 : 5'h0);
  wire        near_path_is_zero = near_path_res_exp == 5'h0 & io_in_near_path_sig_is_zero;
  assign near_path_res_exp =
    io_in_near_path_int_bit
      ? io_in_near_path_out_exp - {1'h0, io_in_near_path_lzc}
        - {4'h0, io_in_near_path_lza_error}
      : 5'h0;
  wire [26:0] _sig_s1_T = {15'h0, io_in_near_path_sig_raw} << io_in_near_path_lzc;
  wire [10:0] sig_s2 =
    io_in_near_path_lza_error ? {_sig_s1_T[9:0], 1'h0} : _sig_s1_T[10:0];
  wire [4:0]  _near_path_exp_rounded_T =
    {4'h0, _near_path_rounder_io_cout} + near_path_res_exp;
  wire        near_path_zero_sign = io_in_rm == 3'h2;
  wire        rmin =
    io_in_rm == 3'h1 | near_path_zero_sign & ~io_in_far_path_out_sign | io_in_rm == 3'h3
    & io_in_far_path_out_sign;
  RoundingUnit_4 far_path_rounder (
    .io_in       (_far_path_res_sig_T_21[12:3]),
    .io_roundIn  (_far_path_res_sig_T_21[2]),
    .io_stickyIn (|(_far_path_res_sig_T_21[1:0])),
    .io_signIn   (io_in_far_path_out_sign),
    .io_rm       (io_in_rm),
    .io_out      (_far_path_rounder_io_out),
    .io_cout     (_far_path_rounder_io_cout)
  );
  RoundingUnit_4 near_path_rounder (
    .io_in       (sig_s2[10:1]),
    .io_roundIn  (sig_s2[0]),
    .io_stickyIn (1'h0),
    .io_signIn   (io_in_near_path_out_sign),
    .io_rm       (io_in_rm),
    .io_out      (_near_path_rounder_io_out),
    .io_cout     (_near_path_rounder_io_cout)
  );
  assign io_result =
    io_in_special_case_valid
      ? (io_in_special_case_bits_nan
           ? 16'h7E00
           : {io_in_special_case_bits_inf_sign, 15'h7C00})
      : io_in_sel_far_path
        & ((&_far_path_res_exp_T_4) | _far_path_rounder_io_cout
           & _far_path_res_exp_T_4 == 5'h1E | io_in_far_path_mul_of) | ~io_in_sel_far_path
        & (&_near_path_exp_rounded_T)
          ? {io_in_sel_far_path ? io_in_far_path_out_sign : io_in_near_path_out_sign,
             4'hF,
             ~rmin,
             {10{rmin}}}
          : io_in_sel_far_path
              ? {io_in_far_path_out_sign,
                 {4'h0, _far_path_rounder_io_cout} + _far_path_res_exp_T_4,
                 _far_path_rounder_io_out}
              : {io_in_near_path_out_sign & ~near_path_is_zero | near_path_zero_sign
                   & near_path_is_zero,
                 _near_path_exp_rounded_T,
                 _near_path_rounder_io_out};
endmodule

module TCAddPipe(
  input         clock,
                reset,
                io_in_valid,
  input  [15:0] io_in_bits_a,
                io_in_bits_b,
  input  [2:0]  io_in_bits_rm,
                io_in_bits_ctrl_rm,
  input  [31:0] io_in_bits_ctrl_c,
  input  [3:0]  io_in_bits_ctrl_ctrl_dataType,
                io_in_bits_ctrl_ctrl_dataTypeB,
  input         io_in_bits_ctrl_ctrl_mixPrecision,
                io_in_bits_ctrl_ctrl_Sparisity,
  input  [31:0] io_in_bits_ctrl_ctrl_DAddress,
