  output        io_out_valid,
  output [15:0] io_out_bits_result,
  output [2:0]  io_out_bits_ctrl_rm,
  output [31:0] io_out_bits_ctrl_c,
  output [3:0]  io_out_bits_ctrl_ctrl_dataType,
                io_out_bits_ctrl_ctrl_dataTypeB,
  output        io_out_bits_ctrl_ctrl_mixPrecision,
                io_out_bits_ctrl_ctrl_Sparisity,
  output [31:0] io_out_bits_ctrl_ctrl_DAddress,
  output        io_out_bits_ctrl_ctrl_clear,
  output [7:0]  io_out_bits_ctrl_ctrl_M,
                io_out_bits_ctrl_ctrl_N,
                io_out_bits_ctrl_ctrl_K,
  output [3:0]  io_out_bits_ctrl_ctrl_OutputD_Idx_m_mix,
  output [4:0]  io_out_bits_ctrl_ctrl_OutputD_Idx_n_mix,
  output [5:0]  io_out_bits_ctrl_ctrl_OutputD_Idx_m_f32,
                io_out_bits_ctrl_ctrl_OutputD_Idx_n_f32
);

  wire [2:0]  _s1_io_out_rm;
  wire        _s1_io_out_far_path_out_sign;
  wire        _s1_io_out_near_path_out_sign;
  wire [4:0]  _s1_io_out_near_path_out_exp;
  wire        _s1_io_out_special_case_valid;
  wire        _s1_io_out_special_case_bits_nan;
  wire        _s1_io_out_special_case_bits_inf_sign;
  wire        _s1_io_out_small_add;
  wire        _s1_io_out_far_path_mul_of;
  wire [10:0] _s1_io_out_far_sig_a;
  wire [14:0] _s1_io_out_far_sig_b;
  wire [4:0]  _s1_io_out_far_exp_a_vec_0;
  wire [4:0]  _s1_io_out_far_exp_a_vec_1;
  wire [4:0]  _s1_io_out_far_exp_a_vec_2;
  wire        _s1_io_out_near_path_sig_is_zero;
  wire        _s1_io_out_near_path_lza_error;
  wire        _s1_io_out_near_path_int_bit;
  wire [11:0] _s1_io_out_near_path_sig_raw;
  wire [3:0]  _s1_io_out_near_path_lzc;
  wire        _s1_io_out_sel_far_path;
  reg         REG;
  reg         REG_1;
  reg  [15:0] s1_io_a_r;
  reg  [15:0] s1_io_b_r;
  reg  [2:0]  s1_io_rm_r;
  reg  [2:0]  s2_io_in_r_rm;
  reg         s2_io_in_r_far_path_out_sign;
  reg         s2_io_in_r_near_path_out_sign;
  reg  [4:0]  s2_io_in_r_near_path_out_exp;
  reg         s2_io_in_r_special_case_valid;
  reg         s2_io_in_r_special_case_bits_nan;
  reg         s2_io_in_r_special_case_bits_inf_sign;
  reg         s2_io_in_r_small_add;
  reg         s2_io_in_r_far_path_mul_of;
  reg  [10:0] s2_io_in_r_far_sig_a;
  reg  [14:0] s2_io_in_r_far_sig_b;
  reg  [4:0]  s2_io_in_r_far_exp_a_vec_0;
  reg  [4:0]  s2_io_in_r_far_exp_a_vec_1;
  reg  [4:0]  s2_io_in_r_far_exp_a_vec_2;
  reg         s2_io_in_r_near_path_sig_is_zero;
  reg         s2_io_in_r_near_path_lza_error;
  reg         s2_io_in_r_near_path_int_bit;
  reg  [11:0] s2_io_in_r_near_path_sig_raw;
  reg  [3:0]  s2_io_in_r_near_path_lzc;
  reg         s2_io_in_r_sel_far_path;
  reg  [2:0]  io_out_bits_ctrl_r_rm;
  reg  [31:0] io_out_bits_ctrl_r_c;
  reg  [3:0]  io_out_bits_ctrl_r_ctrl_dataType;
  reg  [3:0]  io_out_bits_ctrl_r_ctrl_dataTypeB;
  reg         io_out_bits_ctrl_r_ctrl_mixPrecision;
  reg         io_out_bits_ctrl_r_ctrl_Sparisity;
  reg  [31:0] io_out_bits_ctrl_r_ctrl_DAddress;
  reg         io_out_bits_ctrl_r_ctrl_clear;
  reg  [7:0]  io_out_bits_ctrl_r_ctrl_M;
  reg  [7:0]  io_out_bits_ctrl_r_ctrl_N;
  reg  [7:0]  io_out_bits_ctrl_r_ctrl_K;
  reg  [3:0]  io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_mix;
  reg  [4:0]  io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_mix;
  reg  [5:0]  io_out_bits_ctrl_r_ctrl_OutputD_Idx_m_f32;
  reg  [5:0]  io_out_bits_ctrl_r_ctrl_OutputD_Idx_n_f32;
  reg  [2:0]  io_out_bits_ctrl_r_1_rm;
  reg  [31:0] io_out_bits_ctrl_r_1_c;
  reg  [3:0]  io_out_bits_ctrl_r_1_ctrl_dataType;
  reg  [3:0]  io_out_bits_ctrl_r_1_ctrl_dataTypeB;
  reg         io_out_bits_ctrl_r_1_ctrl_mixPrecision;
  reg         io_out_bits_ctrl_r_1_ctrl_Sparisity;
  reg  [31:0] io_out_bits_ctrl_r_1_ctrl_DAddress;
  reg         io_out_bits_ctrl_r_1_ctrl_clear;
  reg  [7:0]  io_out_bits_ctrl_r_1_ctrl_M;
  reg  [7:0]  io_out_bits_ctrl_r_1_ctrl_N;
  reg  [7:0]  io_out_bits_ctrl_r_1_ctrl_K;
  reg  [3:0]  io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_m_mix;
  reg  [4:0]  io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_n_mix;
  reg  [5:0]  io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_m_f32;
  reg  [5:0]  io_out_bits_ctrl_r_1_ctrl_OutputD_Idx_n_f32;
  always @(posedge clock) begin
    automatic logic _io_out_bits_ctrl_T_1;
    _io_out_bits_ctrl_T_1 = REG & REG_1;
    if (reset) begin
      REG <= 1'h0;
      REG_1 <= 1'h0;
    end
    else begin
      if (~(~io_out_ready & _io_out_bits_ctrl_T_1))
        REG <= io_in_valid;
      if (~(~io_out_ready & REG_1))
        REG_1 <= REG;
    end
    if (io_in_valid & ~(~io_out_ready & _io_out_bits_ctrl_T_1))
      s1_io_a_r <= io_in_bits_a;
    if (io_in_valid & ~(~io_out_ready & _io_out_bits_ctrl_T_1))
      s1_io_b_r <= io_in_bits_b;
    if (io_in_valid & ~(~io_out_ready & _io_out_bits_ctrl_T_1))
      s1_io_rm_r <= io_in_bits_rm;
    if (REG & ~(~io_out_ready & REG_1)) begin
      s2_io_in_r_rm <= _s1_io_out_rm;
      s2_io_in_r_far_path_out_sign <= _s1_io_out_far_path_out_sign;
      s2_io_in_r_near_path_out_sign <= _s1_io_out_near_path_out_sign;
      s2_io_in_r_near_path_out_exp <= _s1_io_out_near_path_out_exp;
      s2_io_in_r_special_case_valid <= _s1_io_out_special_case_valid;
      s2_io_in_r_special_case_bits_nan <= _s1_io_out_special_case_bits_nan;
      s2_io_in_r_special_case_bits_inf_sign <= _s1_io_out_special_case_bits_inf_sign;
      s2_io_in_r_small_add <= _s1_io_out_small_add;
      s2_io_in_r_far_path_mul_of <= _s1_io_out_far_path_mul_of;
      s2_io_in_r_far_sig_a <= _s1_io_out_far_sig_a;
      s2_io_in_r_far_sig_b <= _s1_io_out_far_sig_b;
      s2_io_in_r_far_exp_a_vec_0 <= _s1_io_out_far_exp_a_vec_0;
      s2_io_in_r_far_exp_a_vec_1 <= _s1_io_out_far_exp_a_vec_1;
      s2_io_in_r_far_exp_a_vec_2 <= _s1_io_out_far_exp_a_vec_2;
      s2_io_in_r_near_path_sig_is_zero <= _s1_io_out_near_path_sig_is_zero;
      s2_io_in_r_near_path_lza_error <= _s1_io_out_near_path_lza_error;
      s2_io_in_r_near_path_int_bit <= _s1_io_out_near_path_int_bit;
      s2_io_in_r_near_path_sig_raw <= _s1_io_out_near_path_sig_raw;
      s2_io_in_r_near_path_lzc <= _s1_io_out_near_path_lzc;
      s2_io_in_r_sel_far_path <= _s1_io_out_sel_far_path;
    end
